const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const networks=[{name:'Base',cls:'base',symbol:'−'},{name:'Solana',cls:'solana',symbol:'≋'},{name:'XRP',cls:'xrp',symbol:'×'},{name:'BSC',cls:'bsc',symbol:'◇'}];
const coin=name=>{const n=networks.find(n=>n.name===name);return n?`<i class="coin ${n.cls}">${n.symbol}</i>`:''},fmt=n=>Number(n||0).toLocaleString(),date=n=>n?new Date(n).toLocaleString():'Not checked';
let state={view:'overview',chain:'All',days:1,page:1,q:'',status:'all'},session={user:null,admin:false},overview=null,items=[],requestId=0;
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
async function api(path,body){const r=await fetch(path,body?{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)}:{});const data=await r.json();if(!r.ok)throw new Error(data.error||'Request failed.');return data}
function query(){return new URLSearchParams({network:state.chain,days:state.days,page:state.page,limit:state.view==='overview'?20:state.view==='transactions'?50:20,q:state.q,status:state.status})}
function notice(text,error=false){$('notice').classList.toggle('hidden',!text);$('notice').textContent=text;$('notice').classList.toggle('error',error)}
function noteError(e){notice(e.message||'Unable to load data. Please retry.',true)}
function setChain(chain){if(!['All',...networks.map(n=>n.name)].includes(chain))throw new Error('Unknown network');state.chain=chain;state.page=1;render()}
function details(title,rows,link){$('dialog-content').innerHTML=`<div class="eyebrow">SOURCE DETAILS</div><h2 class="detail-heading">${esc(title)}</h2>${rows.map(([k,v])=>`<div class="detail-row"><span>${esc(k)}</span><b>${esc(typeof v==='object'?JSON.stringify(v):v)}</b></div>`).join('')}${link&&/^https:\/\//.test(link)?`<p><a class="home-cta" href="${esc(link)}" target="_blank" rel="noopener noreferrer">Open source ↗</a></p>`:''}`;$('details').showModal()}
function countUp(el,n){if(reduced.matches||!Number.isFinite(n)){el.textContent=n;return}const start=performance.now();function frame(t){if(!el.isConnected)return;const p=Math.min((t-start)/500,1);el.textContent=fmt(Math.round(n*(1-(1-p)**3)));if(p<1)requestAnimationFrame(frame)}requestAnimationFrame(frame)}
function renderOverview(data){overview=data;const records=[['DISCOVERED SERVICES',data.services,'Public catalog entries'],['DISCOVERED PROJECTS',data.projects,'Grouped by website origin'],['INDEXED RECEIPTS',data.indexedTransactions,'Indexed sources only'],['FACILITATORS',data.registeredFacilitators,'Documented provider profiles'],['BUYERS',data.buyers,'Settled indexed receipts only'],['SELLERS',data.sellers,'Settled indexed receipts only']];$('metrics').innerHTML=records.map(([label,value,note])=>`<article class="metric enter"><div class="metric-label">${label}</div><strong>${esc(value)}</strong><span class="muted">${note}</span></article>`).join('');$('metrics').querySelectorAll('strong').forEach((e,i)=>countUp(e,records[i][1]));$('chart-total').textContent=fmt(data.indexedTransactions)+' indexed receipts';document.querySelector('.chart-total>.positive').textContent='Selected period';document.querySelector('.activity h2').textContent='Indexed payment activity';document.querySelector('.activity .panel-title p').textContent=state.days?'Indexed settlement records • '+state.days+' days':'All indexed settlement records';document.querySelector('.segmented').classList.add('hidden');$('legend').textContent=state.chain==='All'?'All networks':state.chain;document.querySelector('.chart-footer>span:last-child').textContent='Source-reported receipts';
if(!data.history.length)$('chart').innerHTML='<div class="coverage-empty"><span>⌁</span><h3>No indexed payment history yet</h3><p>Discovery feeds list services, not every payment.<br>BSC router events and authenticated receipt feeds populate this chart.</p><a href="#docs">Read the integration guide ↗</a></div>';else{const hist=data.history,max=Math.max(...hist.map(p=>p.count),1);$('chart').innerHTML=`<svg viewBox="0 0 660 200" role="img" aria-label="Indexed receipts over the selected period">${hist.map((p,i)=>`<rect x="${i*640/hist.length+10}" y="${170-p.count/max*150}" width="${Math.max(2,620/hist.length)}" height="${p.count/max*150}" fill="#6085ff"><title>${esc(date(p.time))}: ${p.count} receipts</title></rect>`).join('')}</svg>`}
document.querySelector('.distribution h2').textContent='Service distribution';document.querySelector('.share-heading>span').textContent='Network catalog entries';document.querySelector('.share-heading>b').textContent=fmt(data.networks.reduce((a,n)=>a+n.services,0));const all=data.networks.reduce((a,n)=>a+n.services,0)||1;document.querySelectorAll('.share-bar i').forEach((e,i)=>e.style.width=data.networks[i].services/all*100+'%');$('network-legend').innerHTML=data.networks.map((n,i)=>`<div class="legend-row"><i style="background:${['#eee','#aaa','#777','#444'][i]}"></i>${n.id}<span>services</span><b>${fmt(n.services)}</b></div>`).join('');$('network-cards').innerHTML=data.networks.filter(n=>state.chain==='All'||state.chain===n.id).map(n=>`<button class="network-card" data-network-info="${n.id}"><div class="network-name">${coin(n.id)}${n.id}<span>↗</span></div><div class="network-kicker">DISCOVERED SERVICES</div><div class="network-value">${fmt(n.services)}</div><div class="network-meta">${n.facilitators} connected facilitators</div></button>`).join('');$('metrics').querySelectorAll('article').forEach((el,i)=>{const dest=['services','projects','transactions','facilitators','buyers','sellers'][i];el.setAttribute('tabindex','0');el.setAttribute('role','link');el.setAttribute('aria-label','Open '+dest);el.onclick=()=>location.hash=dest;el.onkeydown=e=>{if(e.key==='Enter'){location.hash=dest}}});document.querySelectorAll('[data-network-info]').forEach(b=>b.onclick=()=>{const n=data.networks.find(n=>n.id===b.dataset.networkInfo);details(n.id,[['Network ID',n.caip],['Discovered services',n.services],['Connected facilitators',n.facilitators],['Coverage','Partial. Public discovery is not a full transaction index.']])});$('home-networks').innerHTML=data.networks.map((n,i)=>`<button class="index-network" data-home-chain="${n.id}"><span class="index-number">0${i+1}</span>${coin(n.id)}<span class="index-name">${n.id}<small>${n.facilitators} connected sources</small></span><span class="index-value">${fmt(n.services)}<small>services</small></span><span class="index-arrow">↗</span></button>`).join('');document.querySelectorAll('[data-home-chain]').forEach(b=>b.onclick=()=>setChain(b.dataset.homeChain));}
async function render(){const id=++requestId;const custom=['projects','listings','facilitators','learn','sources','docs','submit','submissions','admin','buyers','sellers','bsc','indexers'].includes(state.view)||state.view.startsWith('project/')||state.view.startsWith('origin/')||state.view.startsWith('facilitator/')||state.view.startsWith('tx/')||state.view.startsWith('address/');document.body.classList.toggle('is-home',state.view==='overview');$('home-intro').classList.toggle('hidden',state.view!=='overview');document.querySelector(state.view==='overview'?'.toolbar':'.page-heading').append(document.querySelector('.period'));document.querySelector('.toolbar').classList.toggle('hidden',custom);$('metrics').classList.toggle('hidden',custom);$('overview-panel').classList.toggle('hidden',!['overview','networks'].includes(state.view));$('list-section').classList.toggle('hidden',custom||state.view==='networks');$('custom-view').classList.toggle('hidden',!custom);document.querySelectorAll('[data-view]').forEach(a=>a.classList.toggle('active',a.dataset.view===state.view||(state.view.startsWith('origin/')&&a.dataset.view==='projects')||(state.view.startsWith('tx/')&&a.dataset.view==='transactions')||(state.view.startsWith('facilitator/')&&a.dataset.view==='facilitators')));document.querySelectorAll('[data-chain]').forEach(b=>{b.classList.toggle('selected',b.dataset.chain===state.chain);b.setAttribute('aria-pressed',b.dataset.chain===state.chain)});const title={buyers:'Buyers',sellers:'Sellers',bsc:'BSC network',overview:'Overview',transactions:'Transactions',services:'Services',networks:'Networks',projects:'Project directory',listings:'Reviewed listings',facilitators:'Facilitators',learn:'Learn x402',sources:'Data sources',docs:'Documentation',submit:'List your project',submissions:'My submissions',admin:'Review queue'}[state.view]||'Project details';$('crumb').textContent=title;$('page-title').textContent=title;$('page-description').textContent={buyers:'Buyer addresses from settled indexed receipts.',sellers:'Seller addresses from settled indexed receipts.',bsc:'Connection, indexing progress and coverage for BNB Smart Chain.',transactions:'Indexed Base facilitator-associated transfers, BSC settlements and configured receipt feeds.',services:'Real endpoints discovered through public x402 catalogs.',networks:'Source coverage across the four networks.',projects:'Discover projects and inspect the paid endpoints they publish.',listings:'Community projects reviewed for listing.',facilitators:'Compare providers, capabilities and documented network support.',learn:'Understand the protocol, explore developer tools, and build with x402.',sources:'Connection status, provenance, and coverage for every configured provider.',docs:'List your project, integrate receipt feeds, and understand the data.',submit:'Submit your x402 project for a public listing review.',submissions:'Track your listing requests and review feedback.',admin:'Review submissions before they appear in the directory.'}[state.view]||'';document.querySelector('.period').classList.toggle('hidden',custom&&!['buyers','sellers','facilitators','projects'].includes(state.view)&&!state.view.startsWith('origin/')&&!state.view.startsWith('facilitator/'));$('home-projects').classList.toggle('hidden',state.view!=='overview');$('home-facilitators').classList.toggle('hidden',state.view!=='overview');$('stats-heading').classList.toggle('hidden',state.view!=='overview');$('transaction-lookup').classList.toggle('hidden',state.view!=='transactions');if(state.view==='transactions'){ $('transaction-lookup').innerHTML=transactionSearch();wireTransactionSearch();}notice('Loading current data…');try{if(custom){await renderCustom(id);return}const results=await Promise.all([api('/api/overview?'+query()),state.view==='networks'?Promise.resolve(null):api('/api/'+(state.view==='services'?'services':'transactions')+'?'+query()),state.view==='overview'?api('/api/ecosystem?network='+encodeURIComponent(state.chain)+'&limit=8'):Promise.resolve(null),state.view==='overview'?api('/api/analytics?'+query()):Promise.resolve(null),state.view==='overview'&&['All','Base'].includes(state.chain)?api('/api/analytics?'+query()+'&facilitator=xpay'):Promise.resolve(null)]);if(id!==requestId)return;if(results[2])renderHomeProjects(results[2]);renderOverview(results[0]);if(results[3])renderDashboard(results[3],results[0],results[2],results[4]);if(results[1])renderTable(results[1]);notice('')}catch(e){if(id!==requestId)return;noteError(e);if(custom){$('custom-view').innerHTML='<div class="panel coverage-empty"><h3>Unable to open this page</h3><p>'+esc(e.message)+'</p><button id="custom-retry" class="directory-button">Retry</button><a href="#projects">Back to projects</a></div>';$('custom-retry').onclick=render;return}$('table-body').innerHTML='<tr><td colspan="7" class="empty">Data is unavailable. <button id="retry">Retry</button></td></tr>';$('retry')?.addEventListener('click',render)}}
function renderTable(data){const service=state.view==='services';items=data.items;$('list-title').textContent=service?'Service directory':state.view==='overview'?'Recent indexed receipts':'Indexed transactions';$('list-subtitle').textContent=service?'Provider-reported endpoints · click a row to inspect payment terms':'Indexed settlement evidence · partial coverage';$('view-all').classList.toggle('hidden',state.view!=='overview');$('status').classList.toggle('hidden',service);$('search').placeholder=service?'Search services or endpoints…':'Search transaction, payer or resource…';$('table-head').innerHTML='<tr>'+(service?['Service / endpoint','Networks','Method','Sources']:['Server / seller','Amount','Buyer','Transaction','Recorded time','Chain','Facilitator']).map(h=>`<th>${h}</th>`).join('')+'</tr>';$('table-body').innerHTML=items.length?items.map((r,i)=>`<tr tabindex="0" role="button" data-row="${i}" aria-label="Inspect ${esc(service?r.name:r.transaction)}">${service?`<td><div class="server-cell">${providerLogo(r.name,r.url)}<b><a class="record-link" href="#origin/${encodeURIComponent(new URL(r.url).origin)}">${esc(r.name)} ↗</a></b></div><small class="row-sub">${esc(r.url.slice(0,95))}</small></td><td>${[...new Set(r.accepts.map(a=>a.network))].map(n=>coin(n)+esc(n)).join(' · ')}</td><td>${esc(r.method)}</td><td>${esc(r.sources.join(', '))}</td>`:`<td>${r.project&&!r.project.ambiguous?`<div class="server-cell">${providerLogo(r.project.name,r.project.origin)}<b><a class="record-link" href="#origin/${encodeURIComponent(r.project.origin)}">${esc(r.project.name)}</a></b></div><small class="row-sub">Catalog-reported name</small>`:''}${addressLink(r.network,r.pay_to)}</td><td>${esc(formatUnits(r.amount,r.decimals))}<small class="row-sub" title="${esc(r.asset)}">${r.network==='Base'&&r.asset.toLowerCase()==='0x833589fcd6edb6e08f4c7c32d4f71b54bda02913'?'USDC':esc(r.asset.length>18?r.asset.slice(0,10)+'…'+r.asset.slice(-4):r.asset)}</small></td><td>${addressLink(r.network,r.payer)}</td><td><a class="record-link" href="#tx/${encodeURIComponent(r.network)}/${encodeURIComponent(r.transaction)}">${esc(r.transaction.slice(0,8))}…${esc(r.transaction.slice(-6))} ↗</a><small class="row-sub">${esc(r.status)}</small></td><td>${esc(date(r.timestamp))}</td><td>${coin(r.network)} ${r.network}</td><td><div class="server-cell">${r.facilitator?facilitatorLogo(r.facilitator):''}${esc(r.facilitator||'Unattributed')}</div><small class="row-sub">${r.evidence==='facilitator-associated-authorization-transfer'?'Inferred association':r.evidence==='finalized-router-event'?'Router event':['facilitator-signed-spl-transfer','documented-source-tag-payment'].includes(r.evidence)?'Inferred association':'Source report'}</small></td>`}</tr>`).join(''):'<tr><td colspan="7" class="empty">'+(service?'No matching catalog entries. Try another network or search.':'No payment receipts match this view. Try All indexed history, or look up a transaction hash above. Full network history is not connected.')+'</td></tr>';document.querySelectorAll('[data-row]').forEach(el=>{const open=()=>{const r=items[Number(el.dataset.row)];details(service?r.name:'Payment receipt',service?[['Endpoint',r.url],['Description',r.description],['Method',r.method],['Sources',r.sources.join(', ')],['Payment options',r.accepts],['Last reported update',r.updatedAt],['Evidence','Provider catalog; endpoint and ownership not independently verified.']]:[['Transaction',r.transaction],['Network',r.network],['Amount',formatUnits(r.amount,r.decimals)],['Asset',r.asset],['Source',r.source],['Status',r.status],['Payer',r.payer],['Recipient',r.pay_to],['Resource',r.resource],['Evidence',r.evidence]],service?r.url:r.explorer)};el.onclick=e=>{if(!e.target.closest('a'))open()};el.onkeydown=e=>{if(!e.target.closest('a')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();open()}}});const pages=Math.max(1,Math.ceil(data.total/(state.view==='overview'?20:state.view==='transactions'?50:20)));$('page-number').textContent=state.page+' / '+pages;$('prev').disabled=state.page<=1;$('next').disabled=state.page>=pages;$('result-count').textContent=fmt(data.total)+' results'+(data.partial?' · catalog sync in progress':'');}
function formatUnits(amount,decimals){const s=String(amount).padStart(decimals+1,'0');const fraction=decimals?s.slice(-decimals).replace(/0+$/,''):'';return decimals?s.slice(0,-decimals)+(fraction?'.'+fraction:''):s}
function pager(total){return `<div class="table-bottom"><span>${fmt(total)} results</span><div><button id="custom-prev" ${state.page===1?'disabled':''}>←</button><span>${state.page} / ${Math.max(1,Math.ceil(total/20))}</span><button id="custom-next" ${state.page*20>=total?'disabled':''}>→</button></div></div>`}
function wirePager(){if($('custom-prev'))$('custom-prev').onclick=()=>{state.page--;render()};if($('custom-next'))$('custom-next').onclick=()=>{state.page++;render()}}
async function renderCustom(id){const root=$('custom-view');root.innerHTML='<div class="coverage-empty">Loading…</div>';if(state.view==='indexers'){await renderIndexers(id);return}if(['buyers','sellers','bsc'].includes(state.view)||state.view.startsWith('address/')){await renderParticipants(id);return}if(state.view.startsWith('tx/')){await renderTransaction(id);return}if(['projects','facilitators','learn'].includes(state.view)||state.view.startsWith('origin/')||state.view.startsWith('facilitator/')||state.view.startsWith('tx/')||state.view.startsWith('address/')){await renderEcosystem(id);return}if(state.view==='docs'){root.innerHTML=docs();notice('Listing, discovery and integration documentation');return}if(state.view==='submit'){renderSubmission();notice('Listings are reviewed before publication.');return}if(state.view.startsWith('project/')){const d=await api('/api/projects/'+encodeURIComponent(state.view.slice(8)));if(id!==requestId)return;const p=d.project;root.innerHTML=`<article class="panel project-detail"><div class="eyebrow">${esc(p.status)} LISTING</div><h2>${esc(p.name)}</h2><p>${esc(p.description)}</p><div class="project-actions"><a href="${esc(p.website)}" target="_blank" rel="noopener noreferrer">Website ↗</a><a href="${esc(p.docs)}" target="_blank" rel="noopener noreferrer">Documentation ↗</a></div>${[['Category',p.category],['Networks',p.networks.join(', ')],['Payment terms',p.paymentTerms],['Endpoint',p.endpoint],['Last updated',date(p.updatedAt)],['Review note',p.reviewNote||'Awaiting review']].map(([k,v])=>`<div class="detail-row"><span>${k}</span><b>${esc(v)}</b></div>`).join('')}<h3>Review history</h3>${d.reviews.map(r=>`<p>${esc(date(r.created_at))} · ${esc(r.action)}<br>${esc(r.note)}</p>`).join('')||'<p>No reviews yet.</p>'}<p class="dialog-note">A listing review is not an endorsement, financial audit or guarantee of endpoint uptime.</p></article>`;notice('Project details · source: project submitter and listing review');return}
if(state.view==='sources'){const d=await api('/api/sources');if(id!==requestId)return;root.innerHTML=`<article class="panel source-card"><div class="eyebrow">BASE TRANSFER INDEXER</div><h2>Base authorization transfers</h2><p>State: ${esc(d.base.state)} · ${esc(d.base.error||d.base.coverage)}</p><p>Next block: ${esc(d.base.next_block||'Not started')} · Observed finalized head: ${esc(d.base.head||'Not checked')}</p><p>Checked: ${esc(date(d.base.checked_at))}</p></article><div class="source-intro"><p>${esc(d.coverage)}</p>${session.admin?'<button class="home-cta" id="sync">Refresh public sources</button>':''}</div><article class="panel source-card bsc-panel"><div class="eyebrow">OUR OWN BSC INDEXER</div><h2>BSC settlement indexing</h2><p>State: ${esc(d.bsc.state)} · ${esc(d.bsc.error||d.bsc.coverage)}</p><p>Router: ${esc(d.bsc.contract)}</p><p>Next block: ${esc(d.bsc.next_block||"Not started")} · Finalized head: ${esc(d.bsc.head||"Not checked")}</p><small>Checked: ${esc(date(d.bsc.checked_at))}</small>${session.admin?'<button class="text-button" id="bsc-sync">Run BSC indexer ↗</button>':''}</article><div class="source-grid">${d.items.map(s=>`<article class="panel source-card"><div class="panel-title"><h2 class="identity-heading">${providerLogo(s.name,s.docs||s.url)}${esc(s.name)}</h2><span class="source-state">${esc(s.state.replaceAll('_',' '))}</span></div><p>${esc(s.networks.length?s.networks.join(' · '):'Declared: '+(s.declared.join(' · ')||'Unverified networks'))}</p><p>${esc(s.error||s.note||s.scope)}</p><small>Checked: ${esc(date(s.checkedAt))}</small>${s.catalog?`<p>${fmt(s.catalog.fetched)} target-network entries stored · ${s.catalog.complete?'current sweep complete':'partial catalog sweep'}${s.catalog.error?' · '+esc(s.catalog.error):''}</p>`:''}<a href="${esc(s.docs)}" target="_blank" rel="noopener noreferrer">Provider documentation ↗</a>${s.stats?`<button class="text-button" data-stat="${s.id}">View provider-wide statistics ↗</button>`:''}</article>`).join('')}</div>`;root.querySelectorAll('[data-stat]').forEach(b=>b.onclick=()=>{const s=d.items.find(x=>x.id===b.dataset.stat);details(s.name+' reported statistics',[['Scope','Provider-wide; includes other networks and may include testnets. Not added to our totals.'],['Statistics',s.stats],['Checked',date(s.checkedAt)]],s.docs)});if($('bsc-sync'))$('bsc-sync').onclick=async e=>{e.target.disabled=true;e.target.textContent='Indexing…';try{await api('/api/admin/bsc-sync',{});render()}catch(err){noteError(err);e.target.disabled=false}};if($('sync'))$('sync').onclick=async e=>{e.target.disabled=true;e.target.textContent='Refreshing…';try{await api('/api/admin/sync',{});render()}catch(e){noteError(e);$('sync').disabled=false;$('sync').textContent='Retry refresh'}};notice('Source connectivity is separate from transaction-history coverage.');return}
const mine=state.view==='submissions',admin=state.view==='admin';if((mine||admin)&&!session.user){root.innerHTML=signin();notice('Sign in to view submissions.');return}const d=await api(admin?'/api/admin/submissions':mine?'/api/submissions':'/api/projects?'+query());if(id!==requestId)return;root.innerHTML=`<div class="project-actions"><a class="home-cta" href="#submit">List a project ↗</a><a href="#submissions">My submissions</a>${session.admin?'<a href="#admin">Review queue</a>':''}</div>${!mine&&!admin?'<label class="search directory-search"><input id="project-search" aria-label="Search projects" placeholder="Search projects…" value="'+esc(state.q)+'"></label>':''}<div class="source-grid">${d.items.map(p=>`<article class="panel source-card"><span class="source-state">${esc(p.status)}</span><h2><a href="#project/${p.id}">${esc(p.name)} ↗</a></h2><p>${esc(p.description.slice(0,220))}</p><p>${p.networks.map(n=>coin(n)+' '+n).join(' · ')}</p><small>${esc(p.category)}</small>${p.reviewNote?'<p>'+esc(p.reviewNote)+'</p>':''}${admin?`<div class="review-box"><textarea aria-label="Review note for ${esc(p.name)}" data-note="${p.id}" placeholder="Review evidence and feedback (10+ characters)"></textarea><button data-review="${p.id}" data-status="approved">Approve</button><button data-review="${p.id}" data-status="rejected">Reject</button><button data-review="${p.id}" data-status="pending">Return to review</button></div>`:''}</article>`).join('')||'<div class="coverage-empty"><h3>No projects here yet</h3><p>Submit a project to start the directory.</p></div>'}</div>${!mine&&!admin?pager(d.total):''}`;wirePager();$('project-search')?.addEventListener('change',e=>{state.q=e.target.value;state.page=1;render()});document.querySelectorAll('[data-review]').forEach(b=>b.onclick=async()=>{const note=root.querySelector('[data-note="'+b.dataset.review+'"]').value;b.disabled=true;try{await api('/api/admin/review',{id:b.dataset.review,status:b.dataset.status,note});render()}catch(e){noteError(e);b.disabled=false}});notice(admin?'Administrator review · approvals publish listings immediately.':mine?'Your submissions and reviewer feedback.':'Reviewed community listings. Discovered project origins are available under Projects; endpoint catalogs are under Services.')}
function signin(){return '<div class="panel form-panel"><h2>Sign in to continue</h2><p>Use ChatGPT sign-in to manage your submissions. Your contact email is kept private.</p><a class="home-cta" href="/signin-with-chatgpt?return_to=%2F%23submit" target="_top">Sign in with ChatGPT ↗</a></div>'}
function renderSubmission(){if(!session.user){$('custom-view').innerHTML=signin();return}$('custom-view').innerHTML=`<div class="submit-layout"><form id="project-form" class="panel form-panel"><h2>Project information</h2><p>Share public details only. Never submit wallet keys or API secrets.</p><div class="form-grid"><label>Project name<input name="name" required minlength="2" maxlength="100"></label><label>Category<select name="category"><option>AI & inference</option><option>Data & analytics</option><option>Developer tools</option><option>Search & content</option><option>Infrastructure</option><option>Facilitator</option><option>Other</option></select></label></div><label>Description<textarea name="description" minlength="30" maxlength="2500" required placeholder="What does your project do, and what can someone pay for?"></textarea></label><label>Website<input name="website" type="url" placeholder="https://your-project.com" required></label><fieldset><legend>Supported mainnet networks</legend>${networks.map(n=>`<label><input type="checkbox" name="networks" value="${n.name}"> ${n.name}</label>`).join('')}</fieldset><label>x402 endpoint or discovery URL<input name="endpoint" type="url" placeholder="https://api.your-project.com/resource" required></label><label>Documentation URL<input name="docs" type="url" required placeholder="https://your-project.com/docs"></label><label>Payment terms<textarea name="paymentTerms" required maxlength="2000" placeholder="Network IDs, asset addresses, raw-unit prices, payment scheme and facilitator."></textarea></label><label>Contact email <small>Private · only you and reviewers can see this</small><input name="contact" type="email" required maxlength="200"></label><label class="consent"><input type="checkbox" required> I am authorized to submit this project and these details are accurate.</label><button type="submit" class="home-cta">Submit for review ↗</button><p id="form-message" role="status"></p></form><aside class="submission-help"><h3>Before you submit</h3><p>1. Publish a working x402 endpoint.</p><p>2. Document payment options for your supported networks.</p><p>3. Link public documentation.</p><p>4. Provide an email for the review team.</p><a href="#docs">Read the listing guide ↗</a><p>Submission does not trigger payments or publish your project automatically.</p></aside></div>`;$('project-form').onsubmit=async e=>{e.preventDefault();const f=e.target,fd=new FormData(f),data=Object.fromEntries(fd);data.networks=fd.getAll('networks');const b=f.querySelector('button[type=submit]');b.disabled=true;$('form-message').textContent='Saving submission…';try{const d=await api('/api/submissions',data);$('form-message').innerHTML='Submitted for review. <a href="#project/'+esc(d.id)+'">View your submission ↗</a>';f.reset()}catch(e){$('form-message').textContent=e.message}finally{b.disabled=false}}}
function docs(){return `<div class="docs-layout"><nav class="docs-nav"><a href="#docs" data-doc="listing">List a project</a><a href="#docs" data-doc="inspection">Project details</a><a href="#docs" data-doc="data">Data & coverage</a><a href="#docs" data-doc="api">Read API</a><a href="#docs" data-doc="bsc">BSC indexer</a><a href="#docs" data-doc="receipts">Receipt integration</a></nav><article class="panel docs-body"><section id="listing"><div class="eyebrow">PROJECT LISTING GUIDE</div><h2>Get your project discovered.</h2><p>Listings are free to submit. Sign in, provide the information below, and send your project for review. Facilitator operators should choose the Facilitator category and include the public base URL, supported networks, schemes, authentication requirements and documentation. A reviewed listing does not automatically enable a backend connector.</p><ol><li><b>Prepare your endpoint.</b> Implement x402 and return an HTTP 402 payment challenge for a paid resource. Publish payment requirements and integration documentation.</li><li><b>Declare the network accurately.</b> Base: <code>eip155:8453</code>; Solana mainnet: <code>solana:5eykt4UsFv8P8NJdTREpY1vzqKqZKvdp</code>; XRP Ledger: <code>xrpl:0</code>; BSC: <code>eip155:56</code>. Testnets are not included in mainnet directory counts.</li><li><b>Submit your project.</b> Provide name, category, description, HTTPS website, endpoint, documentation, network selection, payment terms and contact email.</li><li><b>Track review.</b> Open My submissions. Pending entries are visible only to you and administrators. Review notes explain approval or rejection.</li><li><b>Get listed.</b> Approved projects appear in Projects with a shareable detail view. A review checks listing information; it is not a security audit or endorsement.</li></ol><a class="home-cta" href="#submit">Submit your project ↗</a><p>Rejected submissions can be submitted again with corrections. To change an approved listing, contact the site owner for review; self-service editing is not available in this release.</p></section><section id="inspection"><h2>What visitors can inspect</h2><p>A project detail page includes its description, category, supported networks, public website, documentation, x402 endpoint, payment terms, review status, timestamps and review history. Contact emails and account identifiers are not published.</p><p>Services contains separately discovered provider catalog entries. Click a service to inspect its endpoint, HTTP method, exact asset identifier, network, integer amount, recipient and source. A catalog entry is not proof of ownership or current uptime.</p><h3>Reviewer checklist</h3><ul><li>Check that the website and documentation describe the same project.</li><li>Read the public x402 requirements and confirm declared networks and assets.</li><li>Check who controls the endpoint and whether the submitter is authorized.</li><li>Do not send a payment merely to review a listing.</li><li>Record evidence and limitations in the review note before approval.</li></ul></section><section id="data"><h2>Sources, freshness and coverage</h2><p>The Sources page lists every configured provider, documentation, last check, connection state and catalog progress. We monitor public supported-network endpoints and import documented public discovery catalogs. The registry is curated and expanding; it is not an exhaustive index of every x402 deployment.</p><p>A full public-catalog snapshot provides initial coverage. Live refreshes resume in batches of up to 500 records per provider; completed sweeps replace earlier records. Capabilities refresh after 15 minutes on site visits; unfinished catalog sweeps can resume sooner. No permanent background scheduler is currently connected. Administrators can request another refresh. Cached records remain visible when a provider is temporarily unavailable, with its failed-check state.</p><p>Service counts represent unique method + endpoint entries supporting the selected mainnet. A multichain service can appear under multiple networks. Provider-wide statistics may include other chains and testnets, so they are shown separately and never added to the site's payment totals.</p><p>Transaction history comes from our finalized BSC settlement-router index and authenticated, configured receipt feeds. A blockchain token transfer alone is not proof of an x402 purchase. The site does not invent historical transactions or extrapolate USD volume. Missing USD valuations display an em dash.</p><p>No paid data calls are made automatically. Providers requiring credentials, payment or access agreements remain not connected until access is configured.</p></section><section id="api"><h2>Read API</h2><p>All routes use the same origin as this site. The site's current access policy applies; this preview remains private.</p><pre>GET /api/health
GET /api/session
GET /api/sources
GET /api/facilitators?network=All&page=1&limit=20
GET /api/ecosystem?network=All&page=1&limit=20
GET /api/origins/{URL-encoded-origin}
GET /api/overview?network=Base&days=7
GET /api/services?network=All&page=1&limit=20&q=search
GET /api/transactions?network=Solana&days=30&status=settled
GET /api/transaction?network=Base&hash=0x...
GET /api/projects?page=1&limit=20
GET /api/projects/{id}</pre><p><code>network</code>: All, Base, Solana, XRP or BSC. <code>days</code>: 0 (all indexed history), 1, 7 or 30. Page size is 1–100. List responses contain <code>items</code>, <code>total</code> and <code>page</code>. Errors return JSON with <code>error</code> and an appropriate HTTP status.</p><h3>Signed-in listing actions</h3><pre>POST /api/submissions
GET  /api/submissions</pre><p>Use the listing form for submissions. Write requests need a signed-in platform identity, JSON and a same-origin Origin header. A submitter may send up to five requests per day. No browser API secrets are required.</p><h3>Administrator actions</h3><pre>GET  /api/admin/submissions
POST /api/admin/review
POST /api/admin/sync</pre><p>Review body: <code>{id, status, note}</code>. Status is approved, rejected or pending. Notes must be at least 10 characters. The server checks the administrator allowlist on every request.</p></section><section id="bsc"><h2>Our BSC indexer</h2><p>Our backend reads finalized <code>Settled</code> events directly from the published x402-exec router at <code>0x1Ae0E196dC18355aF3a19985faf67354213F833D</code> on BSC mainnet. This is our own database and reader, not a third-party explorer API.</p><p>The indexer verifies chain ID 56, reads the finalized head, checks contract code, decodes the protocol-specific event, reads token decimals and block timestamps, and commits records with a saved checkpoint. It checks the prior finalized block hash before continuing and stops if the checkpoint changes.</p><p>The initial scan starts roughly 2,000 finalized blocks before the first successful run unless an operator sets BSC_START_BLOCK. Every batch is bounded and resumable. No complete historical backfill is claimed. Other routers, direct token transfers and other BSC protocols are excluded until their adapters are verified.</p><p>Use Sources to inspect the cursor and errors. Administrators can run a batch there. For reliable continuous indexing, configure BSC_RPC_URL with a provider supporting eth_getLogs and finalized blocks, then configure the scheduled handler. The default public RPC may rate-limit or deny requests.</p><p>Projects on BSC can still submit listings and publish their supported payment terms. Listing approval alone never converts ordinary token transfers into x402 payments.</p><p><a href="https://github.com/nuwa-protocol/x402-exec" target="_blank" rel="noopener noreferrer">Router specification and deployment reference ↗</a></p></section><section id="receipts"><h2>Connect an authenticated receipt feed</h2><p>Feed connections require an arrangement with a facilitator or authorized source operator. Ask the site owner to configure a dedicated source secret. Never put the secret in a web page or browser bundle.</p><pre>POST /api/ingest/{sourceId}
Content-Type: application/json
X-Timestamp: &lt;current Unix time in milliseconds&gt;
X-Signature: sha256=&lt;HMAC-SHA256 hex&gt;</pre><p>Sign the exact bytes <code>timestamp + "." + rawJsonBody</code>. The timestamp must be within five minutes. Send at most 100 receipts and 100 KB per request.</p><pre>{
  "receipts": [{
    "network": "eip155:8453",
    "transaction": "0x...64 hexadecimal characters...",
    "eventId": "0",
    "payer": "payer address",
    "payTo": "recipient address",
    "resource": "https://example.com/paid-endpoint",
    "asset": "token contract or mint identifier",
    "amount": "1000",
    "decimals": 6,
    "timestamp": 1790250000000,
    "status": "settled"
  }]
}</pre><p>This is a schema example, not a usable transaction. Amounts are decimal integer strings in the asset's smallest unit. Status is settled, pending or failed. Use the token-transfer log index as eventId for multiple payments in one EVM transaction; do not invent new event IDs when retrying.</p><p>Receipts are deduplicated by network, transaction and eventId across providers. The originating source may advance a pending status; confirmed records are immutable. An authenticated source report is not independent chain verification. Feed operators are responsible for honest, validated settlement reports.</p><p>Production scheduling can invoke the Worker's scheduled handler once a scheduler is configured. Without that configuration, public discovery refreshes when visitors use the site. Receipt feeds push independently.</p></section></article></div>`}
function route(){state.view=location.hash.slice(1)||'overview';if(!['overview','transactions','services','networks','projects','listings','facilitators','learn','sources','docs','submit','submissions','admin','buyers','sellers','bsc','indexers'].includes(state.view)&&!state.view.startsWith('project/')&&!state.view.startsWith('origin/')&&!state.view.startsWith('facilitator/')&&!state.view.startsWith('tx/')&&!state.view.startsWith('address/'))state.view='overview';state.page=1;state.q='';$('search').value='';render()}
document.querySelectorAll('[data-chain]').forEach(b=>b.onclick=()=>setChain(b.dataset.chain));$('period').onchange=e=>{state.days=Number(e.target.value);state.page=1;render()};let searchTimer;$('search').oninput=e=>{state.q=e.target.value;state.page=1;clearTimeout(searchTimer);searchTimer=setTimeout(render,300)};$('status').innerHTML='<option value="all">All statuses</option><option value="settled">Settled</option><option value="pending">Pending</option><option value="failed">Failed</option>';$('status').onchange=e=>{state.status=e.target.value;state.page=1;render()};$('prev').onclick=()=>{state.page--;render()};$('next').onclick=()=>{state.page++;render()};$('view-all').onclick=()=>location.hash='transactions';$('compare').onclick=()=>location.hash='networks';$('about').onclick=()=>details('About x402blockchain',[['Scope','Base, Solana, XRP Ledger and BSC'],['Discovery','Public provider-reported catalogs'],['Payments','BSC router events and configured authenticated receipt feeds; direct transaction lookup also available'],['Coverage','Partial; see Sources and Docs']]);document.querySelector('.close').onclick=()=>$('details').close();$('details').onclick=e=>{if(e.target===$('details'))$('details').close()};window.onhashchange=route;document.addEventListener('click',e=>{const a=e.target.closest('[data-doc]');if(a){e.preventDefault();$(a.dataset.doc)?.scrollIntoView({behavior:reduced.matches?'instant':'smooth',block:'start'})}});$('period').value=String(state.days);Promise.all([api('/api/session'),logoReady]).then(([s])=>{session=s;route()}).catch(e=>{route();noteError(e)});
if(document.modelContext?.registerTool)try{Promise.resolve(document.modelContext.registerTool({name:'filter_network',description:'Filter the x402 explorer by network.',inputSchema:{type:'object',properties:{network:{type:'string',enum:['All','Base','Solana','XRP','BSC']}},required:['network'],additionalProperties:false},execute:async({network})=>{setChain(network);return{network,coverage:'partial'}}})).catch(()=>{})}catch{}

function directoryFilters(kind){return `<form id="directory-filter" class="directory-controls"><label class="search"><input name="q" aria-label="Search ${kind}" placeholder="Search ${kind}…" value="${esc(state.q)}"></label><select name="network" aria-label="Network"><option value="All">All networks</option>${networks.map(n=>`<option ${state.chain===n.name?'selected':''}>${n.name}</option>`).join('')}</select><button class="directory-button" type="submit">Search</button></form>`}
function wireDirectory(){const f=$('directory-filter');if(f)f.onsubmit=e=>{e.preventDefault();state.q=f.elements.q.value;state.chain=f.elements.network.value;state.page=1;render()};wirePager()}
function serviceCards(rows){return rows.map((r,i)=>`<article class="endpoint-card"><div><span class="method-tag">${esc(r.method)}</span><b>${esc(new URL(r.url).pathname)}</b></div><p>${esc(r.description.slice(0,220))}</p><div class="project-actions"><span>${[...new Set(r.accepts.map(a=>a.network))].map(n=>coin(n)+' '+esc(n)).join(' · ')}</span><button class="text-button" data-endpoint="${i}">Payment details ↗</button></div></article>`).join('')}
function wireEndpoints(rows){document.querySelectorAll('[data-endpoint]').forEach(b=>b.onclick=()=>{const r=rows[Number(b.dataset.endpoint)];details(r.name,[['Endpoint',r.url],['Method',r.method],['Description',r.description],['Payment options (integer token units)',r.accepts],['Sources',r.sources.join(', ')],['Evidence','Provider catalog; this page does not make a payment.']],r.url)})}
async function renderEcosystem(id){const root=$('custom-view');if(state.view==='learn'){root.innerHTML=learningPage();notice('Protocol guide · links to official specifications and provider documentation.');return}
if(state.view.startsWith('origin/')){const d=await api('/api/origins/'+state.view.slice(7)+'?'+query());if(id!==requestId)return;$('page-title').textContent=d.name;root.innerHTML=`<article class="panel project-detail origin-detail"><div class="eyebrow">DISCOVERED PROJECT · PROVIDER CATALOG</div><h2 class="identity-heading">${providerLogo(d.name,d.website)}${esc(d.name)}</h2><p>${esc(d.description)}</p><div class="project-actions"><a href="${esc(d.website)}" target="_blank" rel="noopener noreferrer">${esc(new URL(d.website).hostname)} ↗</a><span>${d.networks.map(n=>coin(n)+' '+n).join(' · ')}</span></div><div class="directory-summary"><span><b>${fmt(d.total)}</b> published endpoints</span><span><b>${d.sources.length}</b> catalog sources</span></div><p class="evidence-note">Grouped by exact website origin. This is a discovered service provider, not a reviewed submission or proof of ownership. Activity is matched to unambiguous catalog seller addresses.</p><p>Catalog sources: ${d.sources.map(x=>x==="xpay-direct"?`<a href="https://www.api-xpay.com/x402" target="_blank" rel="noopener noreferrer">X Pay official catalog</a>`:`<a href="#facilitator/${encodeURIComponent(x)}">${esc(x)}</a>`).join(' · ')}</p><div id="entity-activity"></div><h3>Endpoints & payment requirements</h3>${serviceCards(d.services)}${pager(d.total)}</article>`;wireEndpoints(d.services);wirePager();const a=await api('/api/analytics?'+query()+'&origin='+encodeURIComponent(d.website));if(id!==requestId)return;const tx=await api('/api/transactions?'+new URLSearchParams({network:state.chain,days:state.days,page:1,limit:100,origin:d.website}));if(id!==requestId)return;$('entity-activity').innerHTML=activityPanel(a)+entityTransactions(tx);notice('Source-attributed project · catalog snapshot '+date(d.snapshotAt));return}
const detail=state.view.startsWith('facilitator/');if(detail||state.view==='facilitators'){const d=await api('/api/facilitators?'+(detail?'limit=100':query()));if(id!==requestId)return;if(detail){const s=d.items.find(s=>s.id===decodeURIComponent(state.view.slice(12)));if(!s)throw new Error('Facilitator not found.');$('page-title').textContent=s.name;root.innerHTML=`<article class="panel project-detail origin-detail"><div class="eyebrow">FACILITATOR PROFILE</div><h2 class="identity-heading">${providerLogo(s.name,s.docs||s.url)}${esc(s.name)}</h2><span class="source-state">${esc(s.state.replaceAll('_',' '))}</span><p>${esc(s.note||s.scope)}</p><div class="project-actions"><a href="${esc(s.docs)}" target="_blank" rel="noopener noreferrer">Documentation ↗</a><a href="${esc(s.reference||s.docs)}" target="_blank" rel="noopener noreferrer">Registry reference ↗</a></div>${[['Base URL',s.url],['Declared networks',s.declared.join(', ')||'Not documented'],['Responding mainnet capabilities',s.networks.join(', ')||'Not verified'],['Last check',date(s.checkedAt)],['Connection error',s.error||'None recorded'],['Catalog endpoints in our directory',fmt(s.services)],['Catalog progress',s.catalog?(s.catalog.complete?'All pages collected':'Partial')+' · '+fmt(s.catalog.offset)+' source records scanned'+(s.catalog.error?' · '+s.catalog.error:''):'No public catalog connected']].map(([k,v])=>`<div class="detail-row"><span>${k}</span><b>${esc(v)}</b></div>`).join('')}<h3>Reported payment capabilities</h3><div class="capability-list">${s.kinds.map(k=>`<span>${esc(k.network)} · ${esc(k.scheme)} · v${esc(k.version)}</span>`).join('')||'<p>No current capabilities returned. Declared networks above are reference metadata.</p>'}</div><h3>Documented facilitator addresses</h3><p class="evidence-note">Addresses come from the linked upstream registry. They are informational references, not payment instructions or proof that every transaction is an x402 payment.</p>${(s.addresses||[]).map(a=>`<div class="address-row"><span>${esc(a.network)}${a.deprecated?' · historical':''}</span><code>${esc(a.address)}</code><small>First transaction reported: ${esc(a.since||'Unknown')}</small></div>`).join('')||'<p>No address registry available for this provider.</p>'}<div id="entity-activity"></div></article>`;const a=await api('/api/analytics?'+query()+'&facilitator='+encodeURIComponent(s.id));if(id!==requestId)return;const tx=await api('/api/transactions?'+new URLSearchParams({network:state.chain,days:state.days,page:1,limit:100,facilitator:s.id}));if(id!==requestId)return;$('entity-activity').innerHTML=activityPanel(a)+entityTransactions(tx);notice('Provider profile · activity from indexed settlement evidence.');return}
root.innerHTML=`<div class="directory-summary"><span><b>${fmt(d.registered)}</b> registered facilitators</span><span><b>${fmt(d.responding)}</b> recent successful checks</span><a href="#docs">How coverage works ↗</a></div>${directoryFilters('facilitators')}<div class="source-grid facilitator-grid">${d.items.map(s=>`<a class="panel source-card facilitator-card" href="#facilitator/${encodeURIComponent(s.id)}"><div class="facilitator-heading">${providerLogo(s.name,s.docs||s.url)}<span class="source-state">${esc(s.state.replaceAll('_',' '))}</span></div><h2>${esc(s.name)} <span>↗</span></h2><p>${esc((s.networks.length?s.networks:s.declared).join(' · ')||'Network support unverified')}</p><div class="facilitator-meta"><span><b>${fmt(s.services)}</b> catalog endpoints</span><span>${(s.addresses||[]).length} documented addresses</span></div><small>${esc(s.error||s.note||'Last check: '+date(s.checkedAt))}</small></a>`).join('')||'<div class="coverage-empty">No matching facilitators.</div>'}</div>${pager(d.total)}`;wireDirectory();notice('Registry combines public facilitator references. Connection status is separate from transaction indexing.');return}
const d=await api('/api/ecosystem?'+query());if(id!==requestId)return;root.innerHTML=`<div class="project-actions"><a class="directory-tab active" href="#projects">Discovered projects</a><a class="directory-tab" href="#listings">Reviewed listings</a><a href="#submit">List your project ↗</a></div><div class="directory-summary"><span><b>${fmt(d.total)}</b> matching project origins</span><span>Real provider catalogs · grouped by website</span></div>${directoryFilters('projects')}<div class="source-grid project-grid">${d.items.map(p=>`<a href="#origin/${p.id}" class="panel source-card discovered-card">${providerLogo(p.name,p.website)}<div class="eyebrow">${esc(new URL(p.website).hostname)}</div><h2>${esc(p.name)} <span>↗</span></h2><p>${esc(p.description.slice(0,200)||'Inspect the catalog endpoints and payment options for this provider.')}</p><div class="project-networks">${p.networks.map(n=>coin(n)+' '+n).join(' · ')}</div><div class="facilitator-meta"><b>${fmt(p.serviceCount)} endpoints</b><small>${p.sources.length} catalog source${p.sources.length===1?'':'s'}</small></div></a>`).join('')||'<div class="coverage-empty"><h3>No matching project origins</h3><p>Try another network or search term.</p></div>'}</div>${pager(d.total)}`;wireDirectory();notice('Discovered listings are provider-reported. Reviewed community submissions have a separate review history.');}
function learningPage(){const resources=[['Protocol & specification','x402 Foundation','https://github.com/x402-foundation/x402','Reference SDKs, payment schemes, extensions and examples.'],['Build a resource server','Official documentation','https://docs.x402.org/','Implement payment requirements and serve a paid API.'],['Discovery & registration','x402scan discovery guide','https://github.com/Merit-Systems/x402scan/blob/main/docs/DISCOVERY.md','Publish OpenAPI payment metadata and discoverable endpoints.'],['Facilitator directory','x402 Foundation','https://github.com/x402-foundation/x402/blob/main/docs/dev-tools/facilitators.md','Compare managed, public and self-hosted facilitator options.'],['BSC settlement router','x402-exec','https://github.com/nuwa-protocol/x402-exec','The documented router used by our BSC event reader.'],['XRP Ledger integration','T54','https://xrpl-x402.t54.ai/','Provider documentation for x402 payments on XRPL.']];return `<div class="learn-intro panel"><div class="eyebrow">THE OPEN PAYMENT STANDARD</div><h2>What happens when an API can ask for payment?</h2><p>x402 uses HTTP 402 to communicate payment requirements. A compatible client chooses a supported option, authorizes payment, and retries the request. The server verifies the payment and returns the resource according to its settlement policy.</p><div class="payment-flow">${[['01','Request','A client asks for a resource.'],['02','402 response','The server describes payment options.'],['03','Authorize','The client signs a payment payload.'],['04','Verify & settle','The server or facilitator validates and submits payment.'],['05','Receive','The resource is returned under the server’s policy.']].map(([n,t,d])=>`<div><span>${n}</span><h3>${t}</h3><p>${d}</p></div>`).join('')}</div></div><div class="source-grid learn-grid">${resources.map(([title,source,url,desc])=>`<a href="${url}" target="_blank" rel="noopener noreferrer" class="panel source-card"><div class="eyebrow">${source}</div><h2>${title} ↗</h2><p>${desc}</p></a>`).join('')}</div><article class="panel docs-body"><h2>The concepts behind the numbers</h2><dl class="glossary"><dt>Service / resource</dt><dd>A callable endpoint and HTTP method. One project may publish thousands of endpoints.</dd><dt>Project origin</dt><dd>A website origin grouped from discovered endpoints. Subdomains can represent separate origins; this is not a verified count of companies.</dd><dt>Facilitator</dt><dd>A provider that helps a server verify and settle payments. A service can also self-facilitate.</dd><dt>Payment scheme</dt><dd>The protocol rules for authorization and settlement. Exact, upto and batch-settlement have different behavior; support depends on the implementation.</dd><dt>Network & asset</dt><dd>The chain identifier and token contract, mint or currency identifier. x402 support does not imply every token is supported.</dd><dt>Discovery vs. transactions</dt><dd>A catalog tells you what may be purchased. Payment history needs separate settlement evidence and indexing.</dd></dl><h3>Publish your project</h3><p>Document your API, publish x402 payment requirements and discovery metadata, then submit your project for review. Include supported networks, assets, pricing and facilitator documentation.</p><div class="project-actions"><a class="home-cta" href="#submit">List your project ↗</a><a href="#docs">Read our integration guide</a></div></article>`}

function renderHomeProjects(data){$('home-projects').innerHTML=`<div class="section-heading"><div><h2>Explore projects</h2><p>Open a project name to inspect its endpoints, networks and payment terms.</p></div><a class="text-button" href="#projects">All ${fmt(data.total)} projects ↗</a></div><div class="home-project-grid">${data.items.map(p=>`<a class="panel home-project" href="#origin/${p.id}"><div>${providerLogo(p.name,p.website)}<span><b>${esc(p.name)}</b><small>${esc(new URL(p.website).hostname)}</small></span><span class="open-arrow">↗</span></div><p>${esc(p.description.slice(0,150)||'View available endpoints and payment requirements.')}</p><div class="home-project-meta"><span>${p.networks.map(n=>coin(n)+' '+n).join(' · ')}</span><b>${fmt(p.serviceCount)} endpoints</b></div></a>`).join('')||'<div class="coverage-empty">No projects found for the selected network.</div>'}</div>`}
const chainExplorers={Base:'https://basescan.org/tx/',Solana:'https://solscan.io/tx/',XRP:'https://livenet.xrpl.org/transactions/',BSC:'https://bscscan.com/tx/'};
function transactionSearch(network=state.chain==='All'?'Base':state.chain,hash=''){return `<article class="panel lookup-panel"><div><h2>Check a transaction</h2><p>Choose its blockchain and paste the full transaction hash.</p></div><form id="transaction-form"><select name="network" aria-label="Transaction network">${networks.map(n=>`<option ${network===n.name?'selected':''}>${n.name}</option>`).join('')}</select><input name="hash" aria-label="Transaction hash" placeholder="Transaction hash or signature" value="${esc(hash)}" required maxlength="100" autocomplete="off" spellcheck="false"><button class="directory-button" type="submit">Check transaction ↗</button></form><p class="evidence-note">This lookup reads the blockchain. It does not prove an x402 purchase. The indexed list below only includes receipts our system has collected.</p></article>`}
function wireTransactionSearch(){const form=$('transaction-form');if(form)form.onsubmit=e=>{e.preventDefault();const n=form.elements.network.value,h=form.elements.hash.value.trim();location.hash='tx/'+encodeURIComponent(n)+'/'+encodeURIComponent(h)}}
async function renderTransaction(id){const parts=state.view.split('/'),network=decodeURIComponent(parts[1]||''),hash=decodeURIComponent(parts[2]||'');$('page-title').textContent='Transaction details';$('page-description').textContent='Blockchain status and available x402 receipt evidence.';const root=$('custom-view');root.innerHTML=transactionSearch(network,hash)+'<div id="transaction-result" class="panel coverage-empty">Checking the network…</div>';wireTransactionSearch();const valid=chainExplorers[network]&&(network==='Solana'?/^[1-9A-HJ-NP-Za-km-z]{80,90}$/:network==='XRP'?/^[\da-fA-F]{64}$/:/^0x[\da-fA-F]{64}$/).test(hash);try{const d=await api('/api/transaction?'+new URLSearchParams({network,hash}));if(id!==requestId)return;const rows=[['Network',d.network],['Transaction hash',d.hash],['Blockchain status',d.status],['Block / ledger / slot',d.block??'Not available'],['Recorded time',d.timestamp?date(d.timestamp):'Not available'],['Sender',d.from||'Not available'],['Recipient / contract',d.to||'See transaction instructions'],...(d.nativeAmount!=null?[['Native value',formatUnits(d.nativeAmount,d.nativeDecimals)+' '+d.nativeSymbol+' (token transfers may differ)']]:[]),...(d.fee?[['Network fee',formatUnits(d.fee.amount,d.fee.decimals)+' '+d.fee.symbol]]:[])];$('transaction-result').className='panel project-detail origin-detail';$('transaction-result').innerHTML=`<div class="eyebrow">BLOCKCHAIN LOOKUP</div><h2>${esc(d.network)} transaction</h2><p class="evidence-note">${esc(d.coverage)}</p>${d.lookupError?'<p>'+esc(d.lookupError)+'</p>':''}${rows.map(([k,v])=>`<div class="detail-row"><span>${esc(k)}</span><b>${esc(v)}</b></div>`).join('')}<div class="project-actions"><a class="home-cta" href="${esc(d.explorer)}" target="_blank" rel="noopener noreferrer">Open blockchain explorer ↗</a><button class="directory-button" id="copy-hash">Copy hash</button><a href="#transactions">Back to transactions</a></div>${d.delivered?'<h3>Delivered amount reported by XRP Ledger</h3><pre>'+esc(typeof d.delivered==='object'?JSON.stringify(d.delivered,null,2):/^\d+$/.test(d.delivered)?formatUnits(d.delivered,6)+' XRP':d.delivered)+'</pre>':''}${d.tokenTransfers?.length?'<h3>Token transfers</h3>'+d.tokenTransfers.map(t=>'<div class="address-row"><span>Raw token units: '+esc(t.rawAmount)+'</span><code>'+esc(t.asset)+'</code><small>'+esc(t.from)+' → '+esc(t.to)+'</small></div>').join(''):''}${d.tokenChanges?.length?'<h3>Token balance changes</h3>'+d.tokenChanges.map(t=>'<div class="address-row"><span>'+esc(t.change)+' raw units</span><code>'+esc(t.asset)+'</code><small>Owner: '+esc(t.owner||'Not reported')+' · decimals: '+esc(t.decimals)+'</small></div>').join(''):''}<h3>Indexed x402 receipt evidence</h3>${d.indexedReceipts.length?d.indexedReceipts.map(r=>`<article class="endpoint-card"><p>${esc(r.source)} · ${esc(r.status)}</p><div class="detail-row"><span>Amount</span><b>${esc(formatUnits(r.amount,r.decimals))}</b></div><div class="detail-row"><span>Asset</span><b>${esc(r.asset)}</b></div><div class="detail-row"><span>Recipient</span><b>${esc(r.pay_to||'Not reported')}</b></div>${r.resource?'<p><a href="#origin/'+encodeURIComponent(new URL(r.resource).origin)+'">View project: '+esc(new URL(r.resource).hostname)+' ↗</a></p>':'<p>Project attribution was not supplied with this receipt.</p>'}</article>`).join(''):'<p>No x402 receipt is indexed for this transaction. It is not included in payment totals.</p>'}`;$('copy-hash').onclick=async e=>{try{await navigator.clipboard.writeText(hash);e.target.textContent='Copied'}catch{e.target.textContent='Select the hash above to copy'}};notice('Lookup complete · no payment was requested or sent.')}catch(e){if(id!==requestId)return;$('transaction-result').innerHTML=`<h3>Transaction lookup unavailable</h3><p>${esc(e.message)}</p>${valid?`<a class="home-cta" href="${chainExplorers[network]+encodeURIComponent(hash)}" target="_blank" rel="noopener noreferrer">Check on ${esc(network)} explorer ↗</a>`:''}<a href="#transactions">Back to transactions</a>`;noteError(e)}}

function addressLink(network,address){return address?`<a class="record-link address-link" title="${esc(address)}" href="#address/${encodeURIComponent(network)}/${encodeURIComponent(address)}">${esc(address.slice(0,7))}…${esc(address.slice(-5))}</a>`:'<span class="muted">Not reported</span>'}
function receiptTable(rows){return `<div class="table-wrap"><table><thead><tr>${['Transaction','Buyer','Seller','Network','Amount / asset','Time'].map(x=>'<th>'+x+'</th>').join('')}</tr></thead><tbody>${rows.map(r=>`<tr><td><a class="record-link" href="#tx/${encodeURIComponent(r.network)}/${encodeURIComponent(r.transaction)}">${esc(r.transaction.slice(0,10))}…${esc(r.transaction.slice(-6))} ↗</a></td><td>${addressLink(r.network,r.payer)}</td><td>${addressLink(r.network,r.pay_to)}</td><td>${coin(r.network)} ${esc(r.network)}</td><td>${esc(formatUnits(r.amount,r.decimals))}<small class="row-sub">${esc(r.asset)}</small></td><td>${esc(date(r.timestamp))}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No indexed receipts in this period. This is not a complete network history.</td></tr>'}</tbody></table></div>`}
async function renderParticipants(id){const root=$('custom-view');if(state.view==='bsc'){const d=await api('/api/bsc/status');if(id!==requestId)return;root.innerHTML=`<article class="panel bsc-status-page"><div class="eyebrow">BNB SMART CHAIN · MAINNET 56</div><h2>BSC indexing status</h2><span class="source-state">${esc(d.state.replaceAll('_',' '))}</span><p>${esc(d.error||'The reader checks finalized settlement events and saves its progress between runs.')}</p><div class="bsc-stat-grid">${[['First indexed block',d.start_block||'Not started'],['Next block',d.next_block||'Not started'],['Last observed finalized head',d.head||'Not checked'],['Blocks scanned',d.scannedBlocks??0]].map(([k,v])=>`<div><span>${k}</span><strong>${typeof v==='number'?fmt(v):esc(v)}</strong></div>`).join('')}</div><p>Last check: ${esc(date(d.checked_at))}</p><h3>What this includes</h3><p>${esc(d.coverage)}</p><div class="detail-row"><span>Settlement router</span><b>${esc(d.contract)}</b></div><p class="evidence-note">Refreshes run when the site is visited. Continuous scheduled indexing is not configured. A caught-up checkpoint only covers this router and the displayed range.</p><div class="project-actions"><a href="${esc(d.docs)}" target="_blank" rel="noopener noreferrer">Router documentation ↗</a><a href="https://bscscan.com/address/${esc(d.contract)}" target="_blank" rel="noopener noreferrer">Inspect contract ↗</a><button class="directory-button" id="bsc-refresh">Refresh status</button>${session.admin?'<button class="directory-button" id="bsc-run">Run indexing batch</button>':''}</div><div class="project-actions"><button class="text-button" id="bsc-projects">Browse BSC projects ↗</button><button class="text-button" id="bsc-transactions">Browse BSC receipts ↗</button></div></article>`;$('bsc-refresh').onclick=render;$('bsc-projects').onclick=()=>{state.chain='BSC';location.hash='projects'};$('bsc-transactions').onclick=()=>{state.chain='BSC';location.hash='transactions'};if($('bsc-run'))$('bsc-run').onclick=async e=>{e.target.disabled=true;try{await api('/api/admin/bsc-sync',{});render()}catch(e){noteError(e)}};notice('BSC status is based on saved checkpoints; full BSC payment history is not indexed.');return}
if(state.view.startsWith('address/')){const parts=state.view.split('/'),network=decodeURIComponent(parts[1]||''),address=decodeURIComponent(parts[2]||'');const d=await api('/api/address?'+new URLSearchParams({network,address,days:0,page:state.page,limit:20}));if(id!==requestId)return;$('page-title').textContent='Address activity';const addressExplorer={Base:'https://basescan.org/address/',BSC:'https://bscscan.com/address/',Solana:'https://solscan.io/account/',XRP:'https://livenet.xrpl.org/accounts/'};root.innerHTML=`<article class="panel address-profile"><div class="eyebrow">${esc(network)} ADDRESS</div><h2 class="full-address">${esc(address)}</h2><p>${fmt(d.total)} retained receipt records involving this address.</p><div class="project-actions"><a href="${addressExplorer[network]+encodeURIComponent(address)}" target="_blank" rel="noopener noreferrer">View full chain activity ↗</a><a href="#buyers">Buyers</a><a href="#sellers">Sellers</a></div><p class="evidence-note">This page shows our indexed receipts only. An address may be shared by multiple users or projects; no real-world identity is inferred.</p>${receiptTable(d.items)}${pager(d.total)}</article>`;wirePager();notice('Address history · all retained indexed records.');return}
const role=state.view,d=await api('/api/participants?role='+role+'&'+query());if(id!==requestId)return;root.innerHTML=`<div class="directory-summary"><span><b>${fmt(d.total)}</b> ${role==='buyers'?'buyer':'seller'} addresses in indexed receipts</span><span>${state.days?'Last '+state.days+' days':'All indexed history'}</span></div>${directoryFilters(role+' addresses')}<div class="panel"><div class="table-wrap"><table><thead><tr><th>Address</th><th>Network</th><th>Transactions</th><th>${role==='buyers'?'Sellers':'Buyers'}</th><th>First seen</th><th>Last seen</th></tr></thead><tbody>${d.items.map(r=>`<tr><td>${addressLink(r.network,r.address)}</td><td>${coin(r.network)} ${r.network}</td><td>${fmt(r.transactions)}</td><td>${fmt(r.counterparties)}</td><td>${esc(date(r.firstSeen))}</td><td>${esc(date(r.lastSeen))}</td></tr>`).join('')||`<tr><td colspan="6" class="empty"><h3>No ${role} indexed for this view yet</h3><p>Full payment feeds are not connected. Catalog services do not provide buyer or seller activity.</p><a class="record-link" href="#transactions">Check an individual transaction ↗</a></td></tr>`}</tbody></table></div>${pager(d.total)}</div><p class="evidence-note">${esc(d.coverage)} Counts represent addresses, not individual people.</p>`;wireDirectory();notice('Buyer and seller analytics use settled indexed receipts. Global coverage is incomplete.');}

function bars(points,key){if(!points.some(p=>p[key]>0))return '<div class="mini-empty">No indexed activity in this period</div>';const max=Math.max(...points.map(p=>p[key]),1);return `<svg class="mini-bars" viewBox="0 0 320 110" preserveAspectRatio="none" role="img" aria-label="${esc(key)} over the selected period">${points.map((p,i)=>`<rect x="${i*320/points.length+1}" y="${108-p[key]/max*100}" width="${Math.max(1,320/points.length-2)}" height="${p[key]/max*100}" rx="2"><title>${esc(date(p.time))}: ${fmt(p[key])} ${esc(key)}</title></rect>`).join('')}</svg>`;}
function renderDashboard(d,o,catalog,xpay){window.dashboardData=d;const homeFacilitators=d.facilitators.filter(f=>f.id!=='xpay').slice(0,xpay?2:3);if(xpay)homeFacilitators.push({id:'xpay',name:'X Pay',website:'https://x-pay.llc',addresses:1,transactions:xpay.totals.transactions,buyers:xpay.totals.buyers,sellers:xpay.totals.sellers,history:xpay.buckets,featured:true});const controls=document.querySelector('.segmented');controls.classList.remove('hidden');controls.innerHTML='<button data-series="bucket" class="selected">Per interval</button><button data-series="cumulative">Cumulative</button>';const draw=mode=>{let total=0;const rows=d.buckets.map(b=>({...b,count:mode==='cumulative'?(total+=b.transactions):b.transactions}));const max=Math.max(1,...rows.map(b=>b.count));$('chart').innerHTML='<svg viewBox="0 0 660 200" role="img" aria-label="Indexed transaction history">'+rows.map((b,i)=>'<rect x="'+(10+i*640/rows.length)+'" y="'+(175-b.count/max*150)+'" width="'+Math.max(2,600/rows.length)+'" height="'+b.count/max*150+'" fill="#517fff"><title>'+esc(date(b.time))+': '+fmt(b.count)+' transactions</title></rect>').join('')+'</svg>';$('chart-total').textContent=fmt(d.totals.transactions)+' transactions';controls.querySelectorAll('button').forEach(b=>b.classList.toggle('selected',b.dataset.series===mode));};controls.querySelectorAll('button').forEach(b=>b.onclick=()=>draw(b.dataset.series));draw('bucket');const cards=[['Transactions',d.totals.transactions,'transactions','transactions'],['Volume','—',null,'docs'],['Buyers',d.totals.buyers,'buyers','buyers'],['Sellers',d.totals.sellers,'sellers','sellers']];$('metrics').innerHTML=cards.map(([label,value,key,link])=>`<a class="metric dashboard-metric" href="#${link}"><div class="metric-label">${label}</div><strong>${typeof value==='number'?fmt(value):value}</strong>${key?bars(d.buckets,key):'<div class="mini-empty">Choose a token below</div>'}</a>`).join('');const volumeCard=$('metrics').children[1];volumeCard.removeAttribute('href');volumeCard.innerHTML='<div class="metric-label">Token volume</div><select id="volume-asset" aria-label="Volume token">'+d.tokenVolumes.map((v,i)=>'<option value="'+i+'">'+esc(v.network+' · '+(v.asset.toLowerCase()==='0x833589fcd6edb6e08f4c7c32d4f71b54bda02913'?'USDC':v.asset.slice(0,9)+'…'))+'</option>').join('')+'</select><strong id="token-volume-value">—</strong><div id="token-volume-chart"></div>';const showVolume=()=>{const v=d.tokenVolumes[Number($('volume-asset').value)];$('token-volume-value').textContent=v?Number(v.volume).toLocaleString(undefined,{maximumSignificantDigits:7}):'—';$('token-volume-chart').innerHTML=v?bars(v.history,'volume'):'No indexed token volume';};$('volume-asset').onchange=showVolume;showVolume();const serverRows=d.sellers.map(s=>`<tr><td><div class="server-cell">${providerLogo(s.project?.name||s.network,s.project?.origin)}<span>${s.project&&!s.project.ambiguous?`<a href="#origin/${encodeURIComponent(s.project.origin)}"><b>${esc(s.project.name)}</b></a><small class="row-sub">Catalog-reported seller · ${esc(new URL(s.project.origin).hostname)}</small>`:addressLink(s.network,s.address)}<small class="row-sub">${s.project?.ambiguous?'Shared address · multiple catalog origins':esc(s.address.slice(0,12)+'…'+s.address.slice(-6))}</small></span></div></td><td>${sparkline(s.history)}</td><td>${fmt(s.transactions)}</td><td>${fmt(s.buyers)}</td><td>${esc(date(s.latest))}</td><td>${coin(s.network)} ${esc(s.network)}</td><td><a class="directory-button" href="#address/${s.network}/${encodeURIComponent(s.address)}">Inspect ↗</a></td></tr>`).join('');$('home-projects').innerHTML=`<div class="section-heading"><div><h2>Top Servers</h2><p>Seller addresses ranked by settled indexed transactions</p></div><a class="text-button" href="#sellers">All sellers ↗</a></div><div class="panel table-wrap"><table><thead><tr><th>Server / seller</th><th>Activity</th><th>Transactions ↓</th><th>Buyers</th><th>Latest</th><th>Chain</th><th></th></tr></thead><tbody>${serverRows||'<tr><td colspan="6" class="empty">No settled seller activity indexed for this network and period.</td></tr>'}</tbody></table></div><div class="section-heading"><div><h2>Discover Projects</h2><p>${fmt(catalog.total)} catalog origins on the selected networks</p></div><a href="#projects" class="text-button">Browse projects ↗</a></div><div class="discovery-strip">${catalog.items.slice(0,4).map(p=>`<a href="#origin/${p.id}" class="panel discovery-item">${providerLogo(p.name,p.website)}<b>${esc(p.name)}</b><small>${fmt(p.serviceCount)} endpoints · ${esc(p.networks.join(', '))}</small></a>`).join('')}</div>`;$('home-facilitators').innerHTML=`<div class="section-heading"><div><h2>Featured Facilitators</h2><p>Selected providers · actual indexed activity for the chosen period</p></div><a href="#facilitators" class="text-button">All ${fmt(o.registeredFacilitators)} facilitators ↗</a></div><div class="analytics-facilitators">${homeFacilitators.map(f=>`<a class="panel analytics-facilitator" href="#facilitator/${encodeURIComponent(f.id)}"><div class="facilitator-identity">${providerLogo(f.name,f.website)}<h3>${esc(f.name)}</h3><p>${fmt(f.addresses)} documented addresses</p>${sparkline(f.history)}<small>${f.featured?'Featured · Base USDC · indexing in progress':'Indexed activity · partial coverage'}</small></div><dl><div><dt>Transactions</dt><dd>${fmt(f.transactions)}</dd></div><div><dt>Buyers</dt><dd>${fmt(f.buyers)}</dd></div><div><dt>Sellers</dt><dd>${fmt(f.sellers)}</dd></div></dl></a>`).join('')||'<div class="panel coverage-empty">No attributed facilitator activity in this period. <a href="#facilitators">Explore the facilitator directory ↗</a></div>'}</div>`;}
$('hero-search').onsubmit=e=>{e.preventDefault();const q=e.target.elements.q.value.trim();location.hash='projects';setTimeout(()=>{state.q=q;state.page=1;render()},0)};

async function renderIndexers(id){const d=await api('/api/v1/indexers');if(id!==requestId)return;const root=$('custom-view');$('page-title').textContent='Our API & indexers';$('page-description').textContent='Direct blockchain readers, our database, and source-attributed APIs.';root.innerHTML=`<div class="project-actions"><a class="home-cta" href="/api/openapi.json" target="_blank" rel="noopener">OpenAPI specification ↗</a><a href="/api/v1/transactions?days=0" target="_blank" rel="noopener">Transactions JSON ↗</a><button id="refresh-indexers" class="directory-button">Refresh status</button></div><p class="evidence-note">${esc(d.operation)} No x402scan paid data feed is used. Public RPC availability and retained history limit coverage.</p><div class="source-grid">${[['Base',d.base],['BSC',d.bsc],['Solana',{state:d.native.items.some(r=>r.network==='Solana'&&!r.error)?'partial':'not_ready',coverage:d.native.solanaAccounts+' documented facilitator accounts. SPL transfers signed by these accounts; inferred association.'}],['XRP',{state:d.native.items.find(r=>r.network==='XRP')?.error?'needs_attention':d.native.items.some(r=>r.network==='XRP')?'partial':'not_checked',coverage:'Validated payments with published T54 SourceTag. The tag is a signal, not authenticated facilitator identity.'}]].map(([network,s])=>`<article class="panel source-card"><h2>${coin(network)} ${network}</h2><span class="source-state">${esc(s.state)}</span><p>${esc(s.coverage)}</p>${s.next_block?`<p>Next block: ${fmt(s.next_block)} · Head: ${fmt(s.head)}</p>`:''}${s.error?`<p class="notice error">${esc(s.error)}</p>`:''}${session.admin?`<button class="directory-button" data-run-chain="${network}">Run a batch</button>`:''}</article>`).join('')}</div><div class="panel source-card"><h2>Base historical backfill</h2><p>${d.baseHistory?.next_block?fmt(d.baseHistory.next_block-d.baseHistory.start_block)+' blocks scanned · '+esc(d.baseHistory.state):'Waiting for the collector'}</p><p>Separate from live collection. Starts with the preceding 24 hours; older history requires an archival starting block.</p>${d.baseHistory?.error?'<p>'+esc(d.baseHistory.error)+'</p>':''}</div><div class="panel source-card"><h2>BSC historical backfill</h2><p>${d.bscHistory?.next_block?fmt(d.bscHistory.next_block-d.bscHistory.start_block)+' blocks scanned · '+esc(d.bscHistory.state):'Waiting for the collector'}</p><p>Independent history cursor for the documented x402-exec router. Other BSC transfers are not automatically classified as x402.</p>${d.bscHistory?.error?'<p>'+esc(d.bscHistory.error)+'</p>':''}</div><h2>Account and ledger checkpoints</h2><div class="panel table-wrap"><table><thead><tr><th>Network</th><th>Reader</th><th>Records observed</th><th>Last checked</th><th>State</th></tr></thead><tbody>${d.native.items.map(r=>`<tr><td>${esc(r.network)}</td><td>${esc(r.facilitator||r.id)}<small class="row-sub">${esc(r.address||('Next ledger: '+r.next))}</small></td><td>${fmt(r.records)}</td><td>${esc(date(r.checkedAt))}</td><td>${esc(r.error||'Partial coverage')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Readers have not completed a batch yet.</td></tr>'}</tbody></table></div>`;$('refresh-indexers').onclick=render;root.querySelectorAll('[data-run-chain]').forEach(b=>b.onclick=async()=>{b.disabled=true;b.textContent='Reading chain…';try{const result=await api('/api/admin/indexers/run',{network:b.dataset.runChain});await render();if(result.error)notice(result.error,true)}catch(e){noteError(e);b.disabled=false;b.textContent='Retry batch'}});notice('Owned read APIs · independent chain readers · partial coverage');}

setInterval(()=>{if(!document.hidden&&!$('details').open&&['overview','transactions','indexers'].includes(state.view)&&!state.q)render()},60000);

function providerLogo(name,website){let candidates=[];try{const u=new URL(website);if(u.protocol==='https:')candidates=[...new Set([...(logoManifest[u.origin]||[]),u.origin+'/favicon.ico',u.origin+'/favicon.svg',u.origin+'/apple-touch-icon.png','https://icons.duckduckgo.com/ip3/'+encodeURIComponent(u.hostname)+'.ico'])].filter(v=>{try{return new URL(v).protocol==='https:'}catch{return false}})}catch{}const src=candidates.shift();return `<span class="provider-monogram logo-wrap" title="${esc(name)}"><span title="Project initials; official logo unavailable" aria-label="${esc(name)} logo placeholder">${esc(String(name||'?').slice(0,2).toUpperCase())}</span>${src?`<img class="provider-logo" src="${esc(src)}" data-logo-next="${esc(JSON.stringify(candidates))}" loading="lazy" referrerpolicy="no-referrer" alt="${esc(name)} logo">`:''}</span>`}
document.addEventListener('error',e=>{const img=e.target;if(!img.matches?.('.provider-logo'))return;let next=[];try{next=JSON.parse(img.dataset.logoNext||'[]')}catch{}const src=next.shift();if(src){img.dataset.logoNext=JSON.stringify(next);img.src=src}else img.remove()},true);
function sparkline(rows,key='transactions'){if(!rows?.some(r=>Number(r[key])>0))return '<span class="quiet-chart">No indexed activity</span>';const max=Math.max(...rows.map(r=>Number(r[key])||0),1),points=rows.map((r,i)=>`${(i*240/Math.max(1,rows.length-1)).toFixed(1)},${(60-(Number(r[key])||0)/max*54).toFixed(1)}`).join(' ');return `<svg class="sparkline" viewBox="0 0 240 64" role="img" aria-label="Indexed transaction activity"><polygon points="0,64 ${points} 240,64" fill="#eaf0ff"/><polyline points="${points}" fill="none" stroke="#3869ff" stroke-width="1.6" vector-effect="non-scaling-stroke"/>${rows.map((r,i)=>`<circle cx="${i*240/Math.max(1,rows.length-1)}" cy="${60-(Number(r[key])||0)/max*54}" r="3" fill="transparent"><title>${esc(date(r.time))}: ${fmt(r[key])} transactions</title></circle>`).join('')}</svg>`}
function activityPanel(d){return `<section class="detail-activity"><div class="section-heading"><h2>Indexed activity</h2><span>${state.days?'Past '+state.days+' days':'All indexed history'}</span></div><div class="detail-metrics">${[['Transactions',d.totals.transactions,'transactions'],['Buyers',d.totals.buyers,'buyers'],['Sellers',d.totals.sellers,'sellers']].map(([label,value,key])=>`<article class="panel"><span>${label}</span><strong>${fmt(value)}</strong>${bars(d.buckets,key)}</article>`).join('')}</div><h3>Token volumes</h3>${d.tokenVolumes?.length?`<div class="token-volumes">${d.tokenVolumes.map(v=>`<div><b>${Number(v.volume).toLocaleString(undefined,{maximumSignificantDigits:8})}</b> <span title="${esc(v.asset)}">${esc(v.asset.length>20?v.asset.slice(0,8)+'…'+v.asset.slice(-5):v.asset)}</span><small>${esc(v.network)} · ${fmt(v.receipts)} receipts</small></div>`).join('')}</div>`:'<p>No settled token amounts indexed for this selection.</p>'}<p class="evidence-note">Token units, not USD. Charts cover retained settlement evidence only. Shared seller addresses are excluded from project attribution.</p></section>`}

function entityTransactions(d){return `<h3>Recent transactions</h3><p>Showing ${fmt(d.items.length)} of ${fmt(d.total)} matching indexed receipts · change the period above to see older activity.</p><div class="table-wrap"><table><thead><tr><th>Seller</th><th>Amount</th><th>Buyer</th><th>Transaction</th><th>Time</th><th>Chain</th></tr></thead><tbody>${d.items.map(r=>`<tr><td>${addressLink(r.network,r.pay_to)}</td><td>${esc(formatUnits(r.amount,r.decimals))}<small class="row-sub" title="${esc(r.asset)}">${esc(r.asset.slice(0,12))}</small></td><td>${addressLink(r.network,r.payer)}</td><td><a class="record-link" href="#tx/${encodeURIComponent(r.network)}/${encodeURIComponent(r.transaction)}">${esc(r.transaction.slice(0,10))}…${esc(r.transaction.slice(-6))}</a></td><td>${esc(date(r.timestamp))}</td><td>${coin(r.network)} ${esc(r.network)}</td></tr>`).join('')||'<tr><td colspan="6">No matching settlement records have been indexed for this period.</td></tr>'}</tbody></table></div>`}
